/// Publishes the current Sequencer working-copy request to the persistent Scene View world.
///
/// Opening/closing Timeline preview rebuilds the transient world once so system registration
/// cannot overlap the dedicated Animation Preview pipeline. Ordinary playhead/document changes
/// keep the same preview world and only replace the logical Timeline player.
pub(crate) fn set_timeline_preview_request(&mut self, request: Option<TimelinePreviewRequest>) {
    let toggled = self.timeline_preview_request.is_some() != request.is_some();
    self.timeline_preview_request = request;
    if toggled {
        self.preview = None;
    }
    if self.timeline_preview_request.is_none() {
        self.timeline_preview_status = None;
    }
}

/// Returns copied production Timeline telemetry from the latest Scene View sample.
pub(crate) fn timeline_preview_status(&self) -> Option<&TimelinePreviewStatus> {
    self.timeline_preview_status.as_ref()
}

